def transform(grid):
    """Fill masked cells with the repeated value for that column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for c in range(w):
        # The underlying column color is repeated below the diagonal; the
        # diagonal itself carries a one-step offset marker.
        vals = [grid[r][c] for r in range(c + 1, h) if grid[r][c] != 0]
        if not vals:
            vals = [grid[r][c] for r in range(h) if grid[r][c] != 0]
        if not vals:
            continue
        fill = Counter(vals).most_common(1)[0][0]
        for r in range(h):
            if out[r][c] == 0:
                out[r][c] = fill
    return out
