 "content": "def transform(grid):
    """Rebuild the cyclic color rows, with the diagonal color duplicated."""
    h, w = len(grid), len(grid[0])
    cycle = []
    for value in grid[0]:
        if value != 0 and value not in cycle:
            cycle.append(value)
    # Rows after the first use the next phase of the same repeating sequence.
    anchor = next(value for value in grid[1] if value != 0)
    start = cycle.index(anchor)
    out = []
    for r in range(h):
        if r == 0:
            out.append([cycle[(cycle.index(grid[0][0]) + c) % len(cycle)]
                        for c in range(w)])
        else:
            # Before the diagonal retain the ordinary sequence; at and after
            # it, shift by one so the diagonal cell duplicates its predecessor.
            out.append([cycle[(start + (c if c < r else c - 1)) % len(cycle)]
                        for c in range(w)])
    return out
